tests:
package exercise

import (
	"testing"
	"time"
)

func TestConfigurableSleeper(t *testing.T) {
	var sleptFor time.Duration
	calls := 0
	spy := func(d time.Duration) {
		calls++
		sleptFor = d
	}

	sleeper := ConfigurableSleeper{duration: 5 * time.Second, sleep: spy}
	sleeper.Sleep()

	if calls != 1 {
		t.Errorf("expected sleep function to be called once, got %d", calls)
	}
	if sleptFor != 5*time.Second {
		t.Errorf("should have slept for %v but slept for %v", 5*time.Second, sleptFor)
	}
}

solution:
package exercise

import "time"

type ConfigurableSleeper struct {
	duration time.Duration
	sleep    func(time.Duration)
}

func (c ConfigurableSleeper) Sleep() {
	c.sleep(c.duration)
}
